-- PF-08B2C4 PRODUCTION POSTFLIGHT — SELECT ONLY. MANUAL EXECUTION ONLY.
-- Compare both fingerprints with the saved pre-flight output.
WITH expected(reward_id,target_type,product_id,variant_flag) AS (VALUES
('157d2e20-293e-4770-9e8d-e04b03aed110'::uuid,'service',NULL::uuid,false),('71b119b8-3b41-4c2d-a391-2c4aebad3f1b','service',NULL,false),('314199e2-3e2d-4a53-9abc-9388c0eb60b6','service',NULL,false),('fe82c247-cc46-4097-9697-6a9e2075d2ed','service',NULL,false),('2797a5b7-d51f-4695-8ff8-2ad1435f0fbb','service',NULL,false),('f4c0b587-ad8b-4170-a132-a1b41638e8ce','service',NULL,false),('4471c0e5-5db1-4525-8884-91facbf8dc08','service',NULL,false),('6bef04ae-ca90-4ab8-aef3-a33974392674','service',NULL,false),('778ebc4e-9559-45c6-9640-042a55aeb209','service',NULL,false),('ca0966bb-79b8-4126-9419-ca2de74ec729','service',NULL,false),('cce9d976-50cb-47d1-9aac-fa20ceb7cd32','service',NULL,false),('f9ec6558-ae36-470f-9c83-11146467d40f','service',NULL,false),('a2fb6799-cf42-4cb2-9f56-bf75537544da','service',NULL,false),
('46709f62-3f5a-4025-965a-c5fcedcec826','store_product','671549a7-ed15-4eab-886d-4dff3f331d4d',true),('a62ef5f8-355e-4bbc-a235-e19572d3e70f','store_product','bd9eb000-971e-4b4d-bdfa-fe0db9b61350',true),('c0aaddaa-6980-4db5-97ac-4e41e2bb4203','store_product','9596fe52-7982-4a26-9140-68a1462c3e6d',false),('4a875fa4-5b51-4f4c-9209-0bf3be66b1d9','store_product','641f2fe6-8fc7-471c-a35e-118ccaa5d4d8',true),('007de8b9-a69b-4749-a6f2-a4f9498d2a89','store_product','6f71f1cd-6058-4521-b762-3a3689c45e79',true),('a0faea73-495e-47db-9bbb-bfa32f291d5c','store_product','e6416369-e3c0-4ec6-97df-c4376a91aa66',false),('86a8408b-4b98-466e-b084-47ff136c1b30','store_product','a79ceb30-7f9c-40ed-a234-c4580c99ca2e',true),('df69b1e0-f1c2-495c-891f-b1c064f74be6','store_product','4de0a099-1451-437b-9a57-6d2e5be749ea',true),('bd301b3d-6f20-417a-820c-d0f2b7c69918','store_product','5a715132-77f5-412e-a817-7135e7e9507f',true),('5edf4f7e-965d-4462-b645-df999872bc17','store_product','204baf4f-f236-42c2-a93d-c4c27ca7d2b5',true),('975e5de0-e691-4e6a-b4bc-e002dbfbf42b','store_product','dc4d1e5c-c321-430a-b35a-468fcedd0bd0',true),('bc0249ca-ea94-448f-afc4-27614468c9c6','store_product','721949fd-bb78-46e5-a723-75e8c97cd240',true),('1b1718ab-aba8-44bb-a2de-d90992e596a7','store_product','f442259b-1e5b-437a-b0ba-3d056d9d617d',false)
), audit AS (SELECT e.*,r.name,r.is_active,r.fulfillment_type,r.store_product_id,r.requires_store_variant,p.is_active product_active FROM expected e LEFT JOIN public.rewards_catalog r ON r.id=e.reward_id LEFT JOIN public.store_products p ON p.id=e.product_id)
SELECT section,payload FROM (
 SELECT 1 ord,'POSTFLIGHT_SUMMARY' section,jsonb_build_object(
 'targets',(SELECT count(*) FROM audit),'service',(SELECT count(*) FROM audit WHERE fulfillment_type='service'),'store_product',(SELECT count(*) FROM audit WHERE fulfillment_type='store_product'),
 'null_types',(SELECT count(*) FROM audit WHERE fulfillment_type IS NULL),'mismatches',(SELECT count(*) FROM audit WHERE is_active IS DISTINCT FROM true OR fulfillment_type IS DISTINCT FROM target_type OR store_product_id IS DISTINCT FROM product_id OR requires_store_variant IS DISTINCT FROM variant_flag OR (target_type='store_product' AND product_active IS DISTINCT FROM true)),
 'variantless_ambiguities',(SELECT count(*) FROM audit a WHERE a.target_type='store_product' AND NOT a.variant_flag AND (SELECT count(*) FROM public.store_product_stock s WHERE s.product_id=a.product_id AND s.is_active)>1),
 'asciugamano_ok',(SELECT a.store_product_id=a.product_id AND a.requires_store_variant AND (SELECT count(*) FROM public.store_product_stock s WHERE s.product_id=a.product_id AND s.is_active)=2 AND EXISTS(SELECT 1 FROM public.store_product_sizes z WHERE z.product_id=a.product_id AND z.is_active AND z.size_label='UNICA') FROM audit a WHERE a.reward_id='46709f62-3f5a-4025-965a-c5fcedcec826'),
 'tubo_ok',(SELECT a.store_product_id=a.product_id AND NOT a.requires_store_variant AND (SELECT count(*) FROM public.store_product_stock s WHERE s.product_id=a.product_id AND s.is_active)=0 AND EXISTS(SELECT 1 FROM public.store_product_sizes z WHERE z.product_id=a.product_id AND z.is_active AND z.size_label='UNICA') FROM audit a WHERE a.reward_id='1b1718ab-aba8-44bb-a2de-d90992e596a7')) payload
 UNION ALL SELECT 2,'MISMATCH_ROWS',coalesce(jsonb_agg(to_jsonb(a) ORDER BY reward_id),'[]') FROM audit a WHERE is_active IS DISTINCT FROM true OR fulfillment_type IS DISTINCT FROM target_type OR store_product_id IS DISTINCT FROM product_id OR requires_store_variant IS DISTINCT FROM variant_flag OR (target_type='store_product' AND product_active IS DISTINCT FROM true)
 UNION ALL SELECT 3,'POSTFLIGHT_FINGERPRINTS',jsonb_build_object(
 'redemptions',md5(coalesce((SELECT string_agg(to_jsonb(x)::text,'|' ORDER BY x.id) FROM public.reward_redemptions x),'')),
 'unrelated_rewards',md5(coalesce((SELECT string_agg(to_jsonb(x)::text,'|' ORDER BY x.id) FROM public.rewards_catalog x WHERE NOT EXISTS(SELECT 1 FROM expected e WHERE e.reward_id=x.id)),'')))
) report ORDER BY ord;
